import{_ as i,a0 as l,w as o,s as d,I as e,x as a,a1 as t,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用 Python 读取电子表格中的数据 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 读取电子表格中的数据 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 读取电子表格中的数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 读取电子表格中的数据 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200330 Using data from spreadsheets in Fedora with Python","title":"使用 Python 读取电子表格中的数据","tag":"202004","desc":""},"relativePath":"202004/20200330 Using data from spreadsheets in Fedora with Python.md","filePath":"[post].md"}'),h={name:"202004/20200330 Using data from spreadsheets in Fedora with Python.md"};function m(g,s,u,c,f,k){const n=l("Link");return o(),d("div",null,[s[22]||(s[22]=e("h1",{id:"使用-python-读取电子表格中的数据",tabindex:"-1"},[a("使用 Python 读取电子表格中的数据 "),e("a",{class:"header-anchor",href:"#使用-python-读取电子表格中的数据","aria-label":"Permalink to “使用 Python 读取电子表格中的数据”"},"​")],-1)),s[23]||(s[23]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/03/spreadsheets-python-816x345.jpg",alt:""})],-1)),e("p",null,[t(n,{href:"https://python.org"},{default:p(()=>[...s[0]||(s[0]=[a("Python",-1)])]),_:1}),s[1]||(s[1]=a(" 是最流行、功能最强大的编程语言之一。由于它是自由开源的，因此每个人都可以使用。大多数 Fedora 系统都已安装了该语言。Python 可用于多种任务，其中包括处理逗号分隔值（CSV）数据。CSV文件一开始往往是以表格或电子表格的形式出现。本文介绍了如何在 Python 3 中处理 CSV 数据。",-1))]),s[24]||(s[24]=r(`<p>CSV 数据正如其名。CSV 文件按行放置数据，数值之间用逗号分隔。每行由相同的<em>字段</em>定义。简短的 CSV 文件通常易于阅读和理解。但是较长的数据文件或具有更多字段的数据文件可能很难用肉眼解析，因此在这种情况下计算机做得更好。</p><p>这是一个简单的示例，其中的字段是 <code>Name</code>、<code>Email</code> 和 <code>Country</code>。在此例中，CSV 数据将字段定义作为第一行，尽管并非总是如此。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name,Email,Country</span></span>
<span class="line"><span>John Q. Smith,jqsmith@example.com,USA</span></span>
<span class="line"><span>Petr Novak,pnovak@example.com,CZ</span></span>
<span class="line"><span>Bernard Jones,bjones@example.com,UK</span></span></code></pre></div><h3 id="从电子表格读取-csv" tabindex="-1">从电子表格读取 CSV <a class="header-anchor" href="#从电子表格读取-csv" aria-label="Permalink to “从电子表格读取 CSV”">​</a></h3><p>Python 包含了一个 <code>csv</code> 模块，它可读取和写入 CSV 数据。大多数电子表格应用，无论是原生（例如 Excel 或 Numbers）还是基于 Web 的（例如 Google Sheet），都可以导出 CSV 数据。实际上，许多其他可发布表格报告的服务也可以导出为 CSV（例如，PayPal）。</p><p>Python <code>csv</code> 模块有一个名为 <code>DictReader</code> 的内置读取器方法，它可以将每个数据行作为有序字典 （<code>OrderedDict</code>） 处理。它需要一个文件对象访问 CSV 数据。因此，如果上面的文件在当前目录中为 <code>example.csv</code>，那么以下代码段是获取此数据的一种方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>f = open(&#39;example.csv&#39;, &#39;r&#39;)</span></span>
<span class="line"><span>from csv import DictReader</span></span>
<span class="line"><span>d = DictReader(f)</span></span>
<span class="line"><span>data = []</span></span>
<span class="line"><span>for row in d:</span></span>
<span class="line"><span>    data.append(row)</span></span></code></pre></div><p>现在，内存中的 <code>data</code> 对象是 <code>OrderedDict</code> 对象的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[OrderedDict([(&#39;Name&#39;, &#39;John Q. Smith&#39;),</span></span>
<span class="line"><span>               (&#39;Email&#39;, &#39;jqsmith@example.com&#39;),</span></span>
<span class="line"><span>               (&#39;Country&#39;, &#39;USA&#39;)]),</span></span>
<span class="line"><span>  OrderedDict([(&#39;Name&#39;, &#39;Petr Novak&#39;),</span></span>
<span class="line"><span>               (&#39;Email&#39;, &#39;pnovak@example.com&#39;),</span></span>
<span class="line"><span>               (&#39;Country&#39;, &#39;CZ&#39;)]),</span></span>
<span class="line"><span>  OrderedDict([(&#39;Name&#39;, &#39;Bernard Jones&#39;),</span></span>
<span class="line"><span>               (&#39;Email&#39;, &#39;bjones@example.com&#39;),</span></span>
<span class="line"><span>               (&#39;Country&#39;, &#39;UK&#39;)])]</span></span></code></pre></div><p>引用这些对象很容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; print(data[0][&#39;Country&#39;])</span></span>
<span class="line"><span>USA</span></span>
<span class="line"><span>&gt;&gt;&gt; print(data[2][&#39;Email&#39;])</span></span>
<span class="line"><span>bjones@example.com</span></span></code></pre></div><p>顺便说一句，如果你需要处理没有字段名标题行的 CSV 文件，那么 <code>DictReader</code> 类可以让你定义它们。在上面的示例中，添加 <code>fieldnames</code> 参数并传递一系列名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>d = DictReader(f, fieldnames=[&#39;Name&#39;, &#39;Email&#39;, &#39;Country&#39;])</span></span></code></pre></div><h3 id="真实例子" tabindex="-1">真实例子 <a class="header-anchor" href="#真实例子" aria-label="Permalink to “真实例子”">​</a></h3><p>我最近想从一长串人员名单中随机选择一个中奖者。我从电子表格中提取的 CSV 数据是一个简单的名字和邮件地址列表。</p><p>幸运的是，Python 有一个有用的 <code>random</code> 模块，可以很好地生成随机值。该模块 <code>Random</code> 类中的 <code>randrange</code> 函数正是我需要的。你可以给它一个常规的数字范围（例如整数），以及它们之间的步长值。然后，该函数会生成一个随机结果，这意味着我可以在数据的总行数范围内获得一个随机整数（或者说是行号）。</p><p>这个小程序运行良好：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from csv import DictReader</span></span>
<span class="line"><span>from random import Random</span></span>
<span class="line"><span></span></span>
<span class="line"><span>d = DictReader(open(&#39;mydata.csv&#39;))</span></span>
<span class="line"><span>data = []</span></span>
<span class="line"><span>for row in d:</span></span>
<span class="line"><span>    data.append(row)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>r = Random()</span></span>
<span class="line"><span>winner = data[r.randrange(0, len(data), 1)]</span></span>
<span class="line"><span>print(&#39;The winner is:&#39;, winner[&#39;Name&#39;])</span></span>
<span class="line"><span>print(&#39;Email address:&#39;, winner[&#39;Email&#39;])</span></span></code></pre></div><p>显然，这个例子非常简单。电子表格本身包含了复杂的分析数据的方法。但是，如果你想在电子表格应用之外做某事，Python 或许是一种技巧！</p>`,19)),e("p",null,[s[4]||(s[4]=a("题图由 ",-1)),t(n,{href:"https://unsplash.com/@isaacmsmith?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:p(()=>[...s[2]||(s[2]=[a("Isaac Smith",-1)])]),_:1}),s[5]||(s[5]=a(" 拍摄，发表于 ",-1)),t(n,{href:"https://unsplash.com/s/photos/spreadsheets?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:p(()=>[...s[3]||(s[3]=[a("U​​nsplash",-1)])]),_:1}),s[6]||(s[6]=a("。",-1))]),s[25]||(s[25]=e("hr",null,null,-1)),e("p",null,[s[8]||(s[8]=a("via: ",-1)),t(n,{href:"https://fedoramagazine.org/using-data-from-spreadsheets-in-fedora-with-python/"},{default:p(()=>[...s[7]||(s[7]=[a("https://fedoramagazine.org/using-data-from-spreadsheets-in-fedora-with-python/",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=a("作者：",-1)),t(n,{href:"https://fedoramagazine.org/author/pfrields/"},{default:p(()=>[...s[9]||(s[9]=[a("Paul W. Frields",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:p(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[19]||(s[19]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const x=i(h,[["render",m]]);export{C as __pageData,x as default};
